package com.speechnotes.app.logic

/**
 * The hub normalizer chain for the Phonon Unigram tokenizer — ordered data,
 * applied before the Metaspace pre-tokenizer (see [PhononTokenizer]).
 *
 * Ported verbatim from PhononNormalizerTable.swift (speechnotes-ios), itself
 * GENERATED by Scripts/gen-phonon-normalizer.py from the
 * onnx-community/phonon-31m-en-ONNX tokenizer.json (Apache-2.0): Replace
 * steps carry the ICU-translated regex (\\uXXXX -> \\x{...}); java.util.regex
 * compiles every pattern verbatim, with TWO documented translations:
 *  1. ICU accepts the bare derived property \\p{Alphabetic} while Java
 *     requires the Is-prefixed form \\p{IsAlphabetic} (identical property,
 *     same matches; the fixture test pins the behavior).
 *  2. \\s and \\S are written as the EXPLICIT reference whitespace set
 *     (the Rust `regex` \\s = the White_Space property the hub's normalizer
 *     runs on, and ICU \\s agrees). Reason: Android's java.util.regex is
 *     ASCII-only for \\s AND its Pattern.compile REJECTS the
 *     UNICODE_CHARACTER_CLASS flag with "Unsupported flags: 256" (flag
 *     value 0x100 — desktop-JVM-only), which this port hit on device.
 *     Explicit classes are identical on the desktop JVM, on Android, and
 *     in the reference. \\p{Cc} and \\p{N} are native Java categories.
 * Regenerate only if the hub re-exports the tokenizer.
 */
sealed interface PhononNormalizerStep {
    data class Replace(val pattern: String, val replacement: String) : PhononNormalizerStep
    data object Strip : PhononNormalizerStep
    data class Prepend(val text: String) : PhononNormalizerStep
}

